<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · SlideAuthPanel</h1>
      <p class="demo-page__lead">
        来自 video-code 的「拟态滑动登录注册页面」：登录时表单占左边 60%、右侧是「Hello Friend」引导，
        切到注册时两块面板左右互换，中间那条拟态分割线跟着滑过去，表单内容的切换发生在动画中点。
        原 demo 是一整页固定 880×560 的卡片，组件里宽度自适应宿主、高度与动画时长都是 props，
        窄屏自动降级成「顶部 Tab + 单表单」。
      </p>
    </header>

    <section class="sa-demo">
      <div class="sa-demo__head">
        <h2 class="demo-page__section-title">登录态与注册态</h2>
        <code class="sa-demo__tag">mode</code>
      </div>
      <p class="demo-card__text">
        下面这块就是组件本体，点右侧的「SIGN UP / SIGN IN」或上面的按钮可以在两态之间滑动切换。
        切换完成后左右两栏的标题、表单字段和文案都会换成对应的一侧。
      </p>

      <div class="sa-demo__toolbar">
        <button class="demo-btn" type="button" @click="mode = 'signin'">切到登录</button>
        <button class="demo-btn demo-btn--ghost" type="button" @click="mode = 'signup'">切到注册</button>
        <span class="sa-demo__count">当前：<code>{{ mode }}</code></span>
      </div>

      <div class="sa-demo__stage">
        <SlideAuthPanel
          v-model:mode="mode"
          class="sa-demo__panel"
          :height="480"
          @submit="onSubmit"
          @social="onSocial"
          @forgot="lastAction = '点了忘记密码'"
        />
      </div>

      <p class="sa-demo__hint">
        最近一次操作：<code>{{ lastAction }}</code>
      </p>
    </section>

    <DemoPreview class="sa-preview">
      <LevaPlayground
        name="SlideAuthPanel"
        :component="SlideAuthPanel"
        :schema="SlideAuthPanelSchema"
        :presets="{ mode: 'signin' }"
        :listeners="{ submit: (payload: unknown) => (lastAction = `submit ${JSON.stringify(payload)}`) }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>mode</code> 可切登录/注册，<code>accent</code> 换主色，<code>height</code> 调卡片高度，
        <code>duration</code> 是滑动时长（毫秒）；<code>signInAction</code> / <code>signUpAction</code> /
        两套标题与文案都是字符串控件。表单值提交后通过 <code>submit</code> 事件抛出，社交按钮和
        「忘记密码」分别派发 <code>social</code> / <code>forgot</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import SlideAuthPanelSchema from '@melt-js/comps-vue3/src/components/SlideAuthPanel.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const SlideAuthPanel = remoteComponent('SlideAuthPanel')

const mode = ref<'signin' | 'signup'>('signin')
const lastAction = ref('还没操作')

const stageStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '600px',
  padding: '24px',
  background: '#e8edf4',
}

function onSubmit(payload: { mode: string; username: string }) {
  lastAction.value = `${payload.mode} 提交，用户名 ${payload.username || '（空）'}`
}

function onSocial(provider: string) {
  lastAction.value = `点了社交登录：${provider}`
}
</script>

